<?php
require_once __DIR__.'/includes/bootstrap.php';require_login();$pageTitle='Sales History';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();
 try{require_admin();$id=(int)($_POST['sale_id']??0);$reason=trim((string)($_POST['void_reason']??''));if($reason==='')throw new RuntimeException('A reason is required to void a sale.');
  $pdo->beginTransaction();$q=$pdo->prepare("SELECT * FROM sales WHERE id=? AND status='completed' FOR UPDATE");$q->execute([$id]);$sale=$q->fetch();if(!$sale)throw new RuntimeException('Completed sale not found.');
  $items=$pdo->prepare('SELECT product_id,quantity FROM sale_items WHERE sale_id=?');$items->execute([$id]);foreach($items->fetchAll() as $it){$pdo->prepare('UPDATE products SET stock_qty=stock_qty+? WHERE id=?')->execute([$it['quantity'],$it['product_id']]);$pdo->prepare("INSERT INTO inventory_movements(product_id,user_id,movement_type,quantity_change,reference_type,reference_id,notes) VALUES(?,?,'sale_void',?,'sale',?,?)")->execute([$it['product_id'],$_SESSION['user_id'],$it['quantity'],$id,$reason]);}
  $pdo->prepare("UPDATE sales SET status='voided',void_reason=?,voided_by=? WHERE id=?")->execute([$reason,$_SESSION['user_id'],$id]);$pdo->commit();log_action($pdo,'void','sale',$id,$reason);flash('success','Sale voided and inventory restored.');
 }catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();flash('error',$ex instanceof PDOException?'Could not void the sale.':$ex->getMessage());}
 header('Location: sales.php');exit;
}
$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$q=trim((string)($_GET['q']??''));$stmt=$pdo->prepare("SELECT s.*,u.name cashier FROM sales s JOIN users u ON u.id=s.cashier_id WHERE DATE(s.sold_at) BETWEEN ? AND ? AND (s.transaction_no LIKE ?) ORDER BY s.id DESC LIMIT 500");$stmt->execute([$from,$to,"%$q%"]);$sales=$stmt->fetchAll();
$receipt=null;$receiptItems=[];if(isset($_GET['receipt'])){$r=$pdo->prepare('SELECT s.*,u.name cashier FROM sales s JOIN users u ON u.id=s.cashier_id WHERE s.id=?');$r->execute([(int)$_GET['receipt']]);$receipt=$r->fetch();if($receipt){$ri=$pdo->prepare('SELECT * FROM sale_items WHERE sale_id=?');$ri->execute([$receipt['id']]);$receiptItems=$ri->fetchAll();}}
require __DIR__.'/includes/header.php';
?>
<?php if($receipt): ?><div class="receipt-panel panel" id="receipt"><div class="receipt-head"><div class="brand-mark">T</div><h2>Sales receipt</h2><p>TindahanHub · Sari-Sari Store</p><span class="badge <?= $receipt['status']==='completed'?'success':'danger' ?>"><?= e(strtoupper($receipt['status'])) ?></span></div><div class="receipt-meta"><span>Transaction<strong><?= e($receipt['transaction_no']) ?></strong></span><span>Date<strong><?= date('M j, Y g:i A',strtotime($receipt['sold_at'])) ?></strong></span><span>Cashier<strong><?= e($receipt['cashier']) ?></strong></span></div><div class="table-wrap"><table><thead><tr><th>Item</th><th>Qty</th><th>Price</th><th class="align-right">Amount</th></tr></thead><tbody><?php foreach($receiptItems as $it): ?><tr><td><?= e($it['product_name']) ?></td><td><?= e((string)$it['quantity']) ?></td><td><?= money($it['unit_price']) ?></td><td class="align-right"><?= money($it['subtotal']) ?></td></tr><?php endforeach; ?></tbody></table></div><div class="receipt-totals"><div><span>Subtotal</span><strong><?= money($receipt['subtotal']) ?></strong></div><div><span>Discount</span><strong><?= money($receipt['discount']) ?></strong></div><div><span>Total</span><strong><?= money($receipt['total_amount']) ?></strong></div><div><span>Cash received</span><strong><?= money($receipt['cash_received']) ?></strong></div><div><span>Change</span><strong><?= money($receipt['change_amount']) ?></strong></div></div><div class="receipt-actions"><button class="btn primary" onclick="window.print()">Print receipt</button><a class="btn secondary" href="sales.php">Back to history</a></div></div><?php endif; ?>
<div class="panel"><div class="panel-heading"><div><h3>Transaction history</h3><p>Review completed and voided sales.</p></div><a class="btn primary" href="pos.php">＋ New sale</a></div><form class="filter-bar" method="get"><input type="date" name="from" value="<?= e($from) ?>" aria-label="From date"><input type="date" name="to" value="<?= e($to) ?>" aria-label="To date"><input name="q" value="<?= e($q) ?>" placeholder="Transaction number"><button class="btn secondary">Filter</button></form><div class="table-wrap"><table><thead><tr><th>Transaction</th><th>Date</th><th>Cashier</th><th>Status</th><th class="align-right">Total</th><th>Actions</th></tr></thead><tbody><?php foreach($sales as $s): ?><tr><td><strong><?= e($s['transaction_no']) ?></strong></td><td><?= date('M j, Y g:i A',strtotime($s['sold_at'])) ?></td><td><?= e($s['cashier']) ?></td><td><span class="badge <?= $s['status']==='completed'?'success':'danger' ?>"><?= e(ucfirst($s['status'])) ?></span></td><td class="align-right"><?= money($s['total_amount']) ?></td><td><div class="action-group"><a class="btn small secondary" href="sales.php?receipt=<?= $s['id'] ?>">Receipt</a><?php if($s['status']==='completed'&&($_SESSION['role']??'')==='admin'): ?><button type="button" class="btn small danger-outline" onclick="document.getElementById('void-<?= $s['id'] ?>').showModal()">Void</button><?php endif; ?></div><?php if($s['status']==='completed'&&($_SESSION['role']??'')==='admin'): ?><dialog id="void-<?= $s['id'] ?>" class="modal"><form method="post" class="modal-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="sale_id" value="<?= $s['id'] ?>"><h3>Void transaction</h3><p>Voiding restores sold quantities to inventory. This action is recorded.</p><label>Reason *</label><textarea name="void_reason" required maxlength="255"></textarea><div class="modal-actions"><button type="button" class="btn secondary" onclick="this.closest('dialog').close()">Cancel</button><button class="btn danger">Confirm void</button></div></form></dialog><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$sales): ?><tr><td colspan="6"><div class="empty-state compact"><strong>No transactions found</strong><p>Try a different date range or transaction number.</p></div></td></tr><?php endif; ?></tbody></table></div></div>
<?php require __DIR__.'/includes/footer.php'; ?>
